export interface DrillDownDataView {
  loading: boolean;
  error: Error | null;
  skipped?: boolean;
}

export const evaluateDrillDownFullPageErrorState = (
  views: DrillDownDataView[],
): boolean => {
  const activeViews = views.filter((view) => !view.skipped);

  if (activeViews.length === 0) {
    return false;
  }

  if (activeViews.some((view) => view.loading)) {
    return false;
  }

  return activeViews.every((view) => view.error);
};
